mapper.select:
SELECT MIN(bl.player_id) AS player_id, MAX(COALESCE(p.name, gp.display_name)) AS display_name, MAX(p.profile_image_url) AS profile_image_url, MAX(gp.uniform_number) AS uniform_number, BOOL_OR(gp.is_guest) AS guest, COUNT(DISTINCT bl.game_id)::int AS games, COALESCE(SUM(bl.plate_appearances), 0)::int AS plate_appearances, COALESCE(SUM(bl.at_bats), 0)::int AS at_bats, COALESCE(SUM(bl.hits), 0)::int AS hits, COALESCE(SUM(bl.doubles), 0)::int AS doubles, COALESCE(SUM(bl.triples), 0)::int AS triples, COALESCE(SUM(bl.home_runs), 0)::int AS home_runs, COALESCE(SUM(bl.runs_batted_in), 0)::int AS runs_batted_in, COALESCE(SUM(bl.runs), 0)::int AS runs, COALESCE(SUM(bl.walks), 0)::int AS walks, COALESCE(SUM(bl.hit_by_pitch), 0)::int AS hit_by_pitch, COALESCE(SUM(bl.strikeouts), 0)::int AS strikeouts, COALESCE(SUM(bl.sacrifice_hits), 0)::int AS sacrifice_hits, COALESCE(SUM(bl.sacrifice_flies), 0)::int AS sacrifice_flies, COALESCE(SUM(bl.stolen_bases), 0)::int AS stolen_bases, COALESCE(SUM(bl.caught_stealing), 0)::int AS caught_stealing, COALESCE(SUM(bl.reached_on_errors), 0)::int AS reached_on_errors FROM batting_lines bl INNER JOIN game_participants gp ON gp.id = bl.game_participant_id AND gp.game_id = bl.game_id AND gp.team_id = bl.team_id INNER JOIN games g ON g.id = bl.game_id AND g.team_id = bl.team_id INNER JOIN seasons s ON s.id = g.season_id AND s.team_id = bl.team_id LEFT JOIN players p ON p.id = bl.player_id WHERE bl.team_id = #{teamId} AND g.status = #{status}
AND s.year = #{seasonYear}
AND g.tournament_id = #{tournamentId}
AND gp.is_guest = FALSE
GROUP BY CASE WHEN bl.player_id IS NULL THEN 'guest:' || gp.display_name ELSE 'player:' || bl.player_id::text END
